"""
    Initialize parameters for different levels of the network

    Arguments:
    layer_acts -- python array (list) containing the activation functions of each layer in the network
    learning_rate -- float value used as constant for gradient descent

    Returns:
    hyper_parameters -- python dictionary containing hyper_parameters (can be further extended)

    """
def initialize_hyper_parameters(layer_acts: Any, learning_rate: Any) -> object {
    hyper_parameters = {};
    activations = {};
    L = len(layer_acts);
    for l in range(0, L) {
        activations[(l + 1)] = layer_acts[l];
    }
    hyper_parameters["activations"] = activations;
    hyper_parameters["learning_rate"] = learning_rate;
    return hyper_parameters;
}

"""Get a list of admins from the IAM policy."""
def admins_from_iam_policy(iam_policy: Any) -> object {
    roles = ['roles/editor', 'roles/owner', 'roles/viewer', 'roles/appengine.appAdmin'];
    admins = [];
    for binding in iam_policy['bindings'] {
        if (binding['role'] not in roles) {
            continue;
        }
        for member in binding['members'] {
            (user_type, email) = member.split(':', 2);
            if (user_type == 'user') {
                admins.append(email);
            }
        }
    }
    return admins;
}

"""Create convenient output format of taxon biplot coordinates

       taxa is a dict containing 'lineages' and a coord matrix 'coord'

       output is a list of lines, each containing coords for one taxon
    """
def make_biplot_scores_output(taxa: Any) -> object {
    output = [];
    ndims = len(taxa['coord'][1]);
    header = '#Taxon\t' + '\t'.join([('pc%d' % (i + 1)) for i in range(ndims)]);
    output.append(header);
    for (i, taxon) in enumerate(taxa['lineages']) {
        line = taxon + '\t';
        line += '\t'.join(map(str, taxa['coord'][i]));
        output.append(line);
    }
    return output;
}

"""Return contents of docstring."""
def strip_docstring(docstring: Any) -> object {
    docstring = docstring.strip();
    quote_types = ["'''", '"""', "'", '"'];
    for quote in quote_types {
        if (docstring.startswith(quote) and docstring.endswith(quote)) {
            return docstring.split(quote, 1)[1].rsplit(quote, 1)[0].strip();
        }
    }
    raise ValueError('We only handle strings that start with quotes');
}

